import ogImages from "@/content/og-images.json";

// Generated by `npm run images` (scripts/generate-images.mjs). Every file is under 10 KB.

type OgImage = { url: string; width: number; height: number; type: string };
const og = ogImages as Record<string, OgImage>;

/** Social share image for an article, or the site-wide default. */
export function ogImageFor(slug?: string): OgImage {
  return (slug && og[slug]) || og.default;
}

/** Card thumbnail for an article, if one has been generated. */
export function thumbnailFor(slug: string): string | undefined {
  return og[slug] ? `/images/articles/${slug}.webp` : undefined;
}
